 const list=useQuery({queryKey:['labor-requirements',userId,admin,canManage,search,date,status,offset,review],queryFn:()=>localApi.laborRequirementCoverage({search,date,status,offset,review:admin&&review?'SUBMITTED':undefined}),retry:false,staleTime:0,refetchOnMount:'always'});
 const activeDetail=detailIdentity===identity?detail:null;
 const blocked=busy||!!activeDetail,unavailable=requirementQueryUnavailable(list),schemaUnavailable=requirementQueryUnavailable(schema);
 const remember=()=>{if(focus)return;const next=new URLSearchParams(params);next.delete('requirement_code');next.set('req_search',search);next.set('req_date',date);next.set('req_status',status);setParams(next,{replace:true});};
 const open=async(code:string,prefillSource?:NameSuggestionSource)=>{if(guard.current||busy||activeDetail)return;const serial=++generation.current,actorIdentity=identity,scope=identity+'|'+date,current=()=>mounted.current&&serial===generation.current&&actorIdentity===identityRef.current&&currentScope.current===scope;guard.current=true;setWorking(true);setError('');setNamePrefill(null);try{const auth=await captureLocalAuthGuard(userId);auth.assertCurrent();if(!current())return;const fresh=await localApi.laborRequirementDetail(code,date,auth);auth.assertCurrent();if(fresh.code_key!==code)throw new Error('Chi tiết trả về không khớp mã đang mở.');if(current()){setDetailIdentity(actorIdentity);setNamePrefill(prefillSource?{token:crypto.randomUUID(),identity:actorIdentity,date,source:prefillSource}:null);setDetail(fresh);remember();}}catch(error){if(current())setError(note(error));}finally{if(current()){guard.current=false;setWorking(false);}}};
 useEffect(()=>{const code=initialHandoff.current;if(code&&!guard.current){initialHandoff.current=null;void open(code,focus?.prefillSource);}}); // One-shot hand-off; background queries never replace a dirty draft.
 useEffect(()=>{if(!busy)return;const block=(event:MouseEvent)=>{if(event.target instanceof Element&&!event.target.closest('[data-requirement-editor]')){event.preventDefault();event.stopPropagation();}};document.addEventListener('click',block,true);return()=>document.removeEventListener('click',block,true);},[busy]);
